-- AlterTable
ALTER TABLE "District" ADD COLUMN     "code" TEXT;

-- AlterTable
ALTER TABLE "Location" ADD COLUMN     "code" TEXT,
ADD COLUMN     "position" INTEGER NOT NULL DEFAULT 0;

-- CreateIndex
CREATE UNIQUE INDEX "District_code_key" ON "District"("code");

-- CreateIndex
CREATE UNIQUE INDEX "Location_code_key" ON "Location"("code");


-- All of Azerbaijan's cities, districts and settlements from the State Statistics Committee's
-- territorial classification (2024), generated by scripts/import-azstat-regions.py --sql.
-- Nothing is deleted: existing districts and places keep their ids (and so their jobs and profiles);
-- a place already here under its official name only gets its code.

-- Three places were stored without their official kind; the classification lists them as settlements
UPDATE "Location" SET "name" = 'Qabaqçöl qəsəbəsi' WHERE "name" = 'Qabaqçöl' AND "districtId" = (SELECT "id" FROM "District" WHERE "slug" = 'balaken');
UPDATE "Location" SET "name" = 'Əliabad qəsəbəsi' WHERE "name" = 'Əliabad' AND "districtId" = (SELECT "id" FROM "District" WHERE "slug" = 'zaqatala');
UPDATE "Location" SET "name" = 'Turan qəsəbəsi' WHERE "name" = 'Turan' AND "districtId" = (SELECT "id" FROM "District" WHERE "slug" = 'sheki');

